  ('11111111-1111-4111-8111-111111111111', 1, 'Part I — Creating Databases and Tables', 'Write the SQL command to create a database named scc_student_management.', 1, 'CREATE DATABASE scc_student_management', '["CREATE DATABASE scc_student_management","CREATE DATABASE `scc_student_management`"]', false),
  ('11111111-1111-4111-8111-111111111111', 2, 'Part I — Creating Databases and Tables', 'Write the SQL command to select the scc_student_management database for use.', 1, 'USE scc_student_management', '["USE scc_student_management","USE `scc_student_management`"]', false),
  ('11111111-1111-4111-8111-111111111111', 3, 'Part I — Creating Databases and Tables', 'Write the SQL command to display all databases.', 1, 'SHOW DATABASES', '["SHOW DATABASES","SHOW DATABASES;"]', false),
  ('11111111-1111-4111-8111-111111111111', 4, 'Part I — Creating Databases and Tables', 'Write the SQL command to create a table named departments with an id column of type INT.', 1, 'CREATE TABLE departments (id INT)', '["CREATE TABLE departments (id INT)","CREATE TABLE departments (id INT);","CREATE TABLE `departments` (`id` INT)"]', false),
  ('11111111-1111-4111-8111-111111111111', 5, 'Part I — Creating Databases and Tables', 'Write the SQL command to display all tables in the currently selected database.', 1, 'SHOW TABLES', '["SHOW TABLES","SHOW TABLES;"]', false),
  ('11111111-1111-4111-8111-111111111111', 6, 'Part I — Creating Databases and Tables', 'Write the SQL command to display the structure of the students table.', 1, 'DESCRIBE students', '["DESCRIBE students","DESC students","DESCRIBE `students`","DESC `students`"]', false),
  ('11111111-1111-4111-8111-111111111111', 7, 'Part I — Creating Databases and Tables', 'Write the SQL syntax to create a table named students with a student_id column of type INT and a first_name column of type VARCHAR(50).', 1, 'CREATE TABLE students (student_id INT, first_name VARCHAR(50))', '["CREATE TABLE students (student_id INT, first_name VARCHAR(50))","CREATE TABLE students (student_id INT, first_name VARCHAR(50));","CREATE TABLE `students` (`student_id` INT, `first_name` VARCHAR(50))"]', false),
  ('11111111-1111-4111-8111-111111111111', 8, 'Part I — Creating Databases and Tables', 'Write the SQL command to delete the table named students.', 1, 'DROP TABLE students', '["DROP TABLE students","DROP TABLE `students`","DROP TABLE students;"]', false),
  ('11111111-1111-4111-8111-111111111111', 9, 'Part II — Database Constraints', 'Write the syntax to define student_id as the primary key in a table.', 1, 'student_id INT PRIMARY KEY', '["student_id INT PRIMARY KEY","`student_id` INT PRIMARY KEY","student_id INT NOT NULL PRIMARY KEY"]', false),
  ('11111111-1111-4111-8111-111111111111', 10, 'Part II — Database Constraints', 'Write the syntax for a student_number column of type VARCHAR(20) that does not allow NULL values.', 1, 'student_number VARCHAR(20) NOT NULL', '["student_number VARCHAR(20) NOT NULL","`student_number` VARCHAR(20) NOT NULL"]', false),
  ('11111111-1111-4111-8111-111111111111', 11, 'Part II — Database Constraints', 'Write the syntax for an email column of type VARCHAR(100) that does not allow duplicate values.', 1, 'email VARCHAR(100) UNIQUE', '["email VARCHAR(100) UNIQUE","`email` VARCHAR(100) UNIQUE","email VARCHAR(100) NOT NULL UNIQUE","`email` VARCHAR(100) NOT NULL UNIQUE"]', false),
  ('11111111-1111-4111-8111-111111111111', 12, 'Part II — Database Constraints', 'Write the syntax to define department_id as a foreign key referencing department_id in the departments table.', 1, 'department_id INT REFERENCES departments(department_id)', '["department_id INT REFERENCES departments(department_id)","department_id INT REFERENCES departments (department_id)","`department_id` INT REFERENCES `departments` (`department_id`)"]', false),
  ('11111111-1111-4111-8111-111111111111', 13, 'Part II — Database Constraints', 'Write the syntax for a year_level column that accepts only values from 1 to 4 using a CHECK constraint.', 1, 'year_level INT CHECK (year_level BETWEEN 1 AND 4)', '["year_level INT CHECK (year_level BETWEEN 1 AND 4)","year_level INT CHECK (year_level >= 1 AND year_level <= 4)","`year_level` INT CHECK (`year_level` BETWEEN 1 AND 4)"]', false),
  ('11111111-1111-4111-8111-111111111111', 14, 'Part II — Database Constraints', 'Write the SQL command to create a students table with student_id INT PRIMARY KEY and student_number VARCHAR(20) NOT NULL UNIQUE.', 1, 'CREATE TABLE students (student_id INT PRIMARY KEY, student_number VARCHAR(20) NOT NULL UNIQUE)', '["CREATE TABLE students (student_id INT PRIMARY KEY, student_number VARCHAR(20) NOT NULL UNIQUE)","CREATE TABLE students (student_id INT PRIMARY KEY, student_number VARCHAR(20) NOT NULL UNIQUE);"]', false),
  ('11111111-1111-4111-8111-111111111111', 15, 'Part II — Database Constraints', 'Write the SQL command to create a table named subjects with subject_code VARCHAR(20) as its primary key and subject_name VARCHAR(100) as a required field.', 1, 'CREATE TABLE subjects (subject_code VARCHAR(20) PRIMARY KEY, subject_name VARCHAR(100) NOT NULL)', '["CREATE TABLE subjects (subject_code VARCHAR(20) PRIMARY KEY, subject_name VARCHAR(100) NOT NULL)","CREATE TABLE subjects (subject_code VARCHAR(20) PRIMARY KEY, subject_name VARCHAR(100) NOT NULL);"]', false),
  ('11111111-1111-4111-8111-111111111111', 16, 'Part III — Altering Tables', 'Write the SQL command to add a phone_number column of type VARCHAR(15) to the students table.', 1, 'ALTER TABLE students ADD phone_number VARCHAR(15)', '["ALTER TABLE students ADD phone_number VARCHAR(15)","ALTER TABLE students ADD COLUMN phone_number VARCHAR(15)"]', false),
  ('11111111-1111-4111-8111-111111111111', 17, 'Part III — Altering Tables', 'Write the SQL command to add an address column of type VARCHAR(150) to the students table.', 1, 'ALTER TABLE students ADD address VARCHAR(150)', '["ALTER TABLE students ADD address VARCHAR(150)","ALTER TABLE students ADD COLUMN address VARCHAR(150)"]', false),
  ('11111111-1111-4111-8111-111111111111', 18, 'Part III — Altering Tables', 'Write the SQL command to modify the first_name column to VARCHAR(100).', 1, 'ALTER TABLE students MODIFY first_name VARCHAR(100)', '["ALTER TABLE students MODIFY first_name VARCHAR(100)","ALTER TABLE students ALTER COLUMN first_name TYPE VARCHAR(100)","ALTER TABLE students MODIFY COLUMN first_name VARCHAR(100)"]', false),
  ('11111111-1111-4111-8111-111111111111', 19, 'Part III — Altering Tables', 'Write the SQL command to remove the phone_number column from the students table.', 1, 'ALTER TABLE students DROP COLUMN phone_number', '["ALTER TABLE students DROP COLUMN phone_number","ALTER TABLE students DROP phone_number"]', false),
  ('11111111-1111-4111-8111-111111111111', 20, 'Part III — Altering Tables', 'Write the SQL command to rename the students table to student_records.', 1, 'RENAME TABLE students TO student_records', '["RENAME TABLE students TO student_records","ALTER TABLE students RENAME TO student_records"]', false),
  ('11111111-1111-4111-8111-111111111111', 21, 'Part III — Altering Tables', 'Write the SQL command to add a NOT NULL constraint to the subject_name column by modifying it to VARCHAR(100).', 1, 'ALTER TABLE subjects MODIFY subject_name VARCHAR(100) NOT NULL', '["ALTER TABLE subjects MODIFY subject_name VARCHAR(100) NOT NULL","ALTER TABLE subjects ALTER COLUMN subject_name TYPE VARCHAR(100) NOT NULL"]', false),
  ('11111111-1111-4111-8111-111111111111', 22, 'Part III — Altering Tables', 'Write the SQL command to add a column named birth_date of type DATE to the students table.', 1, 'ALTER TABLE students ADD birth_date DATE', '["ALTER TABLE students ADD birth_date DATE","ALTER TABLE students ADD COLUMN birth_date DATE"]', false),
  ('11111111-1111-4111-8111-111111111111', 23, 'Part III — Altering Tables', 'Write the SQL command to delete all records from the students table without deleting the table itself.', 1, 'DELETE FROM students', '["DELETE FROM students","TRUNCATE TABLE students"]', false),
  ('11111111-1111-4111-8111-111111111111', 24, 'Part IV — SELECT Queries', 'Write the SQL command to display all columns and records from the students table.', 1, 'SELECT * FROM students', '["SELECT * FROM students","SELECT * FROM students;"]', false),
