  ('11111111-1111-4111-8111-111111111111', 29, 'Part IV — SELECT Queries', 'Write the SQL command to display all students ordered by last_name in descending order.', 1, 'SELECT * FROM students ORDER BY last_name DESC', '["SELECT * FROM students ORDER BY last_name DESC","SELECT * FROM students ORDER BY last_name DESC;"]', false),
