  ('11111111-1111-4111-8111-111111111111', 31, 'Part IV — SELECT Queries', 'Write the SQL command to display students whose year_level is greater than 2.', 1, 'SELECT * FROM students WHERE year_level > 2', '["SELECT * FROM students WHERE year_level > 2","SELECT * FROM students WHERE year_level>2"]', false),
  ('11111111-1111-4111-8111-111111111111', 32, 'Part IV — SELECT Queries', 'Write the SQL command to display students whose year_level is less than or equal to 3.', 1, 'SELECT * FROM students WHERE year_level <= 3', '["SELECT * FROM students WHERE year_level <= 3","SELECT * FROM students WHERE year_level <=3"]', false),
  ('11111111-1111-4111-8111-111111111111', 33, 'Part IV — SELECT Queries', 'Write the SQL command to display students whose first names begin with the letter A.', 1, 'SELECT * FROM students WHERE first_name LIKE "A%"', '["SELECT * FROM students WHERE first_name LIKE \"A%\"","SELECT * FROM students WHERE first_name LIKE ''A%''","SELECT * FROM students WHERE first_name LIKE ''A%'' ;"]', false),
  ('11111111-1111-4111-8111-111111111111', 34, 'Part IV — SELECT Queries', 'Write the SQL command to display students whose last names contain the letters son.', 1, 'SELECT * FROM students WHERE last_name LIKE "%son%"', '["SELECT * FROM students WHERE last_name LIKE \"%son%\"","SELECT * FROM students WHERE last_name LIKE ''%son%''"]', false),
  ('11111111-1111-4111-8111-111111111111', 35, 'Part IV — SELECT Queries', 'Write the SQL command to display enrollments with grades between 75 and 90, inclusive.', 1, 'SELECT * FROM enrollments WHERE grade BETWEEN 75 AND 90', '["SELECT * FROM enrollments WHERE grade BETWEEN 75 AND 90","SELECT * FROM enrollments WHERE grade >= 75 AND grade <= 90"]', false),
  ('11111111-1111-4111-8111-111111111111', 36, 'Part IV — SELECT Queries', 'Write the SQL command to display students whose department_id is either 1 or 3.', 1, 'SELECT * FROM students WHERE department_id IN (1, 3)', '["SELECT * FROM students WHERE department_id IN (1, 3)","SELECT * FROM students WHERE department_id = 1 OR department_id = 3"]', false),
  ('11111111-1111-4111-8111-111111111111', 37, 'Part IV — SELECT Queries', 'Write the SQL command to display students whose email address is not NULL.', 1, 'SELECT * FROM students WHERE email IS NOT NULL', '["SELECT * FROM students WHERE email IS NOT NULL","SELECT * FROM students WHERE email IS NOT NULL;"]', false),
  ('11111111-1111-4111-8111-111111111111', 38, 'Part V — Aggregate Functions', 'Write the SQL command to count all records in the students table.', 1, 'SELECT COUNT(*) FROM students', '["SELECT COUNT(*) FROM students","SELECT COUNT(*) FROM students;"]', false),
