  ('11111111-1111-4111-8111-111111111111', 40, 'Part V — Aggregate Functions', 'Write the SQL command to calculate the total units in the enrollments table.', 1, 'SELECT SUM(units) FROM enrollments', '["SELECT SUM(units) FROM enrollments","SELECT SUM(units) FROM enrollments;"]', false),
  ('11111111-1111-4111-8111-111111111111', 41, 'Part V — Aggregate Functions', 'Write the SQL command to retrieve the highest grade from the enrollments table.', 1, 'SELECT MAX(grade) FROM enrollments', '["SELECT MAX(grade) FROM enrollments","SELECT MAX(grade) FROM enrollments;"]', false),
