  ('11111111-1111-4111-8111-111111111111', 44, 'Part V — Aggregate Functions', 'Write the SQL command to calculate the average units in the enrollments table.', 1, 'SELECT AVG(units) FROM enrollments', '["SELECT AVG(units) FROM enrollments","SELECT AVG(units) FROM enrollments;"]', false),
